base=[p for p in j['posts'] if not p['id'].startswith('atlas:')]
# μετονομασία κατηγορίας
for p in base:
    p['categories']=[GR if c=='Ελλάδα' else c for c in p['categories']]
new=[]
for it in A:
    slug,title,lat,spk,cats,txt=it[:6];spo=it[6] if len(it)>6 else None
    html=''.join('<p>'+x+'</p>' for x in txt)
    wiki='https://el.wikipedia.org/wiki/Special:Search?search='+urllib.parse.quote(lat.split(' (')[0])
    plain=' '.join(txt)
    p={'id':'atlas:'+slug,'title':title,'originalTitle':title,'status':'LIVE','published':'2010-01-01T00:00:00Z','updated':'2010-01-01T00:00:00Z','categories':cats,'content':'<p><b>'+title+'</b> ('+lat+')</p>'+html,'searchText':title+' '+lat+' '+plain,'snippet':(title+' ('+lat+') '+plain)[:200],'image':'','isCode':'False','url':wiki,'atlas':1,'spk':spk}
    if spo:p['spo']=spo
    new.append(p)
j['posts']=base+new
cc={}
for p in j['posts']:
    for c in p['categories']:cc[c]=cc.get(c,0)+1
j['categories']=sorted(cc,key=lambda s:s);j['categoryCounts']=cc
open(DST,'w',encoding='utf8').write(t[:a]+json.dumps(j,ensure_ascii=False,separators=(',',':'))+t[b:])
print(len(new),'atlas;',cc.get(GR),'ελληνικά')
